1	import OpenAI from "openai";
2	import { init, shutdown, span, wrapOpenAI } from "neatlogs";
3	import {
4	  ChatCompletionMessageParam,
5	  ChatCompletionTool,
6	} from "openai/resources/chat/completions";
7	
8	function requireEnv(name: string): string {
9	  const value = process.env[name];
10	  if (!value) throw new Error(`Set ${name} in .env`);
11	  return value;
12	}
13	
14	const model = requireEnv("OPENAI_MODEL");
15	const apiKey = requireEnv("OPENAI_API_KEY");
16	
17	await init({
18	  apiKey: requireEnv("NEATLOGS_API_KEY"),
19	  workflowName: "npm-advisor",
20	});
21	
22	const client = wrapOpenAI(
23	  new OpenAI({
24	    apiKey: apiKey,
25	  }),
26	);
27	
28	const MAX_STEPS = 8;
29	
30	const tools: ChatCompletionTool[] = [
31	  {
32	    type: "function",
33	    function: {
34	      name: "search_packages",
35	      description:
36	        "Search the npm registry by keywords. Returns the 8 most downloaded matches with name, description and weekly downloads. " +
37	        'Results depend heavily on wording, so try 2 or 3 phrasings (e.g. "react form", "react form library", "react hook form").',
38	      parameters: {
39	        type: "object",
40	        properties: {
41	          query: {
42	            type: "string",
43	            description: 'Search terms, e.g. "date formatting"',
44	          },
45	        },
46	        required: ["query"],
47	        additionalProperties: false,
48	      },
49	      strict: true,
50	    },
51	  },
52	  {
53	    type: "function",
54	    function: {
55	      name: "get_package_info",
56	      description:
57	        "Look up one npm package by exact name. Returns description, latest version, last publish date, license, " +
58	        "repository, weekly downloads and whether it is deprecated, or found: false if no such package exists. " +
59	        "Packages with the same repository belong to the same project. " +
60	        "Use it to check packages you suspect exist but search missed, and to verify your top picks before recommending.",
61	      parameters: {
62	        type: "object",
63	        properties: {
64	          name: {
65	            type: "string",
66	            description:
67	              'Exact package name, e.g. "formik" or "@tanstack/react-form"',
68	          },
69	        },
70	        required: ["name"],
71	        additionalProperties: false,
72	      },
73	      strict: true,
74	    },
75	  },
76	];
77	
78	interface SearchResult {
79	  name: string;
80	  description: string;
81	  weeklyDownloads: number;
82	}
83	
84	interface NpmSearchResponse {
85	  objects: {
86	    package: { name: string; description?: string; date?: string };
87	    downloads?: { weekly: number };
88	  }[];
89	}
90	
91	interface NpmLatestManifest {
92	  version: string;
93	  description?: string;
94	  license?: string;
95	  deprecated?: string;
96	  repository?: string | { url?: string };
97	}
98	
99	type PackageInfo =
100	  | { found: false; name: string }
101	  | {
102	      found: true;
103	      name: string;
104	      description: string;
105	      latestVersion: string;
106	      lastPublished: string | null;
107	      monthsSinceLastPublish: number | null;
108	      license: string | null;
109	      repository: string | null;
110	      weeklyDownloads: number | null;
111	      deprecated: string | null;
112	    };
113	
114	const searchPackages = span(
115	  { kind: "TOOL", toolName: "search_packages" },
116	  async (query: string): Promise<SearchResult[]> => {
117	    const url = `https://registry.npmjs.org/-/v1/search?text=${encodeURIComponent(query)}&size=25`;
118	
119	    const res = await fetch(url);
120	    if (!res.ok) throw new Error(`npm search failed with status ${res.status}`);
121	
122	    const data = (await res.json()) as NpmSearchResponse;
123	
124	    return data.objects
125	      .map((o) => ({
126	        name: o.package.name,
127	        description: o.package.description ?? "",
128	        weeklyDownloads: o.downloads?.weekly ?? 0,
129	      }))
130	      .sort((a, b) => b.weeklyDownloads - a.weeklyDownloads)
131	      .slice(0, 8);
132	  },
133	);
134	
135	const getPackageInfo = span(
136	  { kind: "TOOL", toolName: "get_package_info" },
137	  async (name: string): Promise<PackageInfo> => {
138	    const encoded = encodeURIComponent(name).replace("%40", "@");
139	    const [latestRes, searchRes] = await Promise.all([
140	      fetch(`https://registry.npmjs.org/${encoded}/latest`),
141	      fetch(
142	        `https://registry.npmjs.org/-/v1/search?text=${encodeURIComponent(name)}&size=5`,
143	      ),
144	    ]);
145	
146	    if (latestRes.status === 404) return { found: false, name };
147	    if (!latestRes.ok)
148	      throw new Error(
149	        `npm lookup for ${name} failed with status ${latestRes.status}`,
150	      );
151	
152	    const latest = (await latestRes.json()) as NpmLatestManifest;
153	
154	    const search = searchRes.ok
155	      ? ((await searchRes.json()) as NpmSearchResponse)
156	      : { objects: [] };
157	
158	    const match = search.objects.find((o) => o.package.name === name);
159	
160	    return {
161	      found: true,
162	      name,
163	      description: latest.description ?? "",
164	      latestVersion: latest.version,
165	      lastPublished: match?.package.date ?? null,
166	      monthsSinceLastPublish: monthsSince(match?.package.date),
167	      license: latest.license ?? null,
168	      repository: normalizeRepository(latest.repository),
169	      weeklyDownloads: match?.downloads?.weekly ?? null,
170	      deprecated: latest.deprecated ?? null,
171	    };
172	  },
173	);
174	
175	const MS_PER_MONTH = 1000 * 60 * 60 * 24 * 30.44;
176	
177	function monthsSince(isoDate: string | undefined): number | null {
178	  if (!isoDate) return null;
179	  const then = Date.parse(isoDate);
180	  if (Number.isNaN(then)) return null;
181	  return Math.floor((Date.now() - then) / MS_PER_MONTH);
182	}
183	
184	function normalizeRepository(
185	  repo: NpmLatestManifest["repository"],
186	): string | null {
187	  const raw = typeof repo === "string" ? repo : repo?.url;
188	  if (!raw) return null;
189	  return raw
190	    .replace(/^git\+/, "")
191	    .replace(/^github:/, "https://github.com/")
192	    .replace(/^git:\/\//, "https://")
193	    .replace(/\.git$/, "")
194	    .toLowerCase();
195	}
196	
197	async function runTool(name: string, rawArgs: string): Promise<string> {
198	  const args: unknown = JSON.parse(rawArgs);
199	
200	  if (name === "search_packages" && isQueryArgs(args)) {
201	    return JSON.stringify(await searchPackages(args.query));
202	  }
203	
204	  if (name === "get_package_info" && isNameArgs(args)) {
205	    return JSON.stringify(await getPackageInfo(args.name));
206	  }
207	
208	  return JSON.stringify({ error: `Unknown tool or bad args: ${name}` });
209	}
210	
211	function isQueryArgs(value: unknown): value is { query: string } {
212	  return (
213	    typeof value === "object" &&
214	    value !== null &&
215	    "query" in value &&
216	    typeof value.query === "string"
217	  );
218	}
219	
220	function isNameArgs(value: unknown): value is { name: string } {
221	  return (
222	    typeof value === "object" &&
223	    value !== null &&
224	    "name" in value &&
225	    typeof value.name === "string"
226	  );
227	}
228	
229	const runAgent = span(
230	  { kind: "AGENT", name: "npm_advisor" },
231	  async (question: string): Promise<string> => {
232	    const messages: ChatCompletionMessageParam[] = [
233	      {
234	        role: "system",
235	        content: [
236	          "You help developers pick npm packages. Follow these steps in order.",
237	          "1. From your own knowledge, name the 3 to 5 packages developers most often choose for this job.",
238	          "2. In your first turn, call get_package_info on each of them and call search_packages to find anything you missed.",
239	          "3. If search shows a strong candidate you have not checked, call get_package_info on it.",
240	          "4. Recommend one package and at most two alternatives. Each must be a library developers install directly for this job.",
241	          "   Skip packages that extend, wrap or ship inside another library. Packages with the same repository are one project: list it once.",
242	          "monthsSinceLastPublish is how long ago the last release was. At 12 or more, the package may be unmaintained:",
243	          "   never make it the main pick, and if you list it as an alternative, say how many months it has been.",
244	          "   High downloads do not mean a package is maintained. Never call a package actively maintained at 12 or more.",
245	          "Give downloads and last publish date for each pick.",
246	        ].join("\n"),
247	      },
248	      { role: "user", content: question },
249	    ];
250	
251	    for (let step = 1; step <= MAX_STEPS; step++) {
252	      const res = await client.chat.completions.create({
253	        model,
254	        messages,
255	        tools,
256	      });
257	
258	      const msg = res.choices[0]?.message;
259	      if (!msg) throw new Error("Model returned no message");
260	      messages.push(msg);
261	
262	      if (!msg.tool_calls?.length) return msg.content ?? "";
263	
264	      const calls = msg.tool_calls.filter((call) => call.type === "function");
265	      const results = await Promise.all(
266	        calls.map(async (call) => {
267	          console.log(
268	            `[step ${step}] ${call.function.name}(${call.function.arguments})`,
269	          );
270	          return {
271	            id: call.id,
272	            content: await runTool(call.function.name, call.function.arguments),
273	          };
274	        }),
275	      );
276	      for (const { id, content } of results) {
277	        messages.push({ role: "tool", tool_call_id: id, content });
278	      }
279	    }
280	    return `Stopped after ${MAX_STEPS} steps without a final answer.`;
281	  },
282	);
283	
284	const advise = span({ kind: "WORKFLOW", name: "advise" }, runAgent);
285	
286	const question =
287	  process.argv.slice(2).join(" ") ||
288	  "Which date library should I use for a Next.js app?";
289	try {
290	  console.log(await advise(question));
291	} finally {
292	  await shutdown();
293	}
